(2, 'A Justiça', 'Platão', 'filosofia', 'edipro', '2005-02-01', 'usado', 1, '96.06', '129.90', 'Este diálogo foi extraído de A República, a mais traduzida, difundida, estudada e influente obra de Platão, consagrada como um dos mais expressivos textos de filosofia de todos os tempos! ', );
